"""Minimal mock LangWatch server for validating the pipeline request shape."""
import json
import re
import threading
from http.server import BaseHTTPRequestHandler, HTTPServer

CAPTURED = {
    "evaluations": [],
    "traces": [],
}


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *a, **k):
        pass

    def _send(self, code, body=None):
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        if body is not None:
            self.wfile.write(json.dumps(body).encode())

    def do_POST(self):
        length = int(self.headers.get("Content-Length", "0") or "0")
        raw = self.rfile.read(length) if length else b""
        try:
            payload = json.loads(raw.decode()) if raw else {}
        except Exception:
            payload = {}

        path = self.path

        if re.search(r"/api/evaluations/.+/evaluate$", path):
            slug = path.split("/api/evaluations/")[1].split("/")[0]
            CAPTURED["evaluations"].append({"slug": slug, "payload": payload})
            return self._send(
                200,
                {
                    "status": "processed",
                    "passed": True,
                    "score": 1.0,
                    "label": "pass",
                    "details": "The answer is faithful to the context and addresses the question.",
                },
            )

        if path.endswith("/api/otel/v1/traces"):
            CAPTURED["traces"].append(payload)
            return self._send(200, {})

        return self._send(200, {})


def serve(port=9911):
    server = HTTPServer(("127.0.0.1", port), Handler)
    server.serve_forever()


if __name__ == "__main__":
    import sys

    port = int(sys.argv[1]) if len(sys.argv) > 1 else 9911
    print(f"mock langwatch on http://127.0.0.1:{port}")
    serve(port)

"""Minimal mock LangWatch server that persists captured requests to disk."""
import json
import os
import re
from http.server import BaseHTTPRequestHandler, HTTPServer

CAP_DIR = "/tmp/mock_captures"
os.makedirs(CAP_DIR, exist_ok=True)


def _dump(name, obj):
    with open(os.path.join(CAP_DIR, name), "a", encoding="utf-8") as fh:
        fh.write(json.dumps(obj, ensure_ascii=False, default=str))
        fh.write("\n")


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *a, **k):
        pass

    def _send(self, code, body=None):
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        if body is not None:
            self.wfile.write(json.dumps(body).encode())

    def do_POST(self):
        length = int(self.headers.get("Content-Length", "0") or "0")
        raw = self.rfile.read(length) if length else b""
        try:
            payload = json.loads(raw.decode()) if raw else {}
        except Exception:
            payload = {}
        path = self.path
        if re.search(r"/api/evaluations/.+/evaluate$", path):
            slug = path.split("/api/evaluations/")[1].split("/")[0]
            _dump("evaluations.jsonl", {"slug": slug, "payload": payload})
            return self._send(
                200,
                {
                    "status": "processed",
                    "passed": True,
                    "score": 1.0,
                    "label": "pass",
                    "details": "The answer is faithful to the context and addresses the question.",
                },
            )
        if path.endswith("/api/otel/v1/traces"):
            _dump("traces.jsonl", payload)
            return self._send(200, {})
        return self._send(200, {})


def serve(port=9911):
    server = HTTPServer(("127.0.0.1", port), Handler)
    server.serve_forever()


if __name__ == "__main__":
    import sys

    port = int(sys.argv[1]) if len(sys.argv) > 1 else 9911
    # clear previous captures
    for f in ("evaluations.jsonl", "traces.jsonl"):
        p = os.path.join(CAP_DIR, f)
        if os.path.exists(p):
            os.remove(p)
    print(f"mock langwatch on http://127.0.0.1:{port}")
    serve(port)

