"""Decode OTLP protobuf trace exports and print span names + parent IDs."""
import sys
from opentelemetry.proto.collector.trace.v1.trace_service_pb2 import (
    ExportTraceServiceRequest,
)


def decode(path):
    with open(path, "rb") as f:
        data = f.read()

    # Split on the separator we inserted between requests.
    chunks = data.split(b"\n---SEP---\n")
    spans = []
    for chunk in chunks:
        chunk = chunk.strip()
        if not chunk:
            continue
        req = ExportTraceServiceRequest()
        try:
            req.ParseFromString(chunk)
        except Exception as e:
            print("parse error:", e, file=sys.stderr)
            continue
        for rs in req.resource_spans:
            for ss in rs.scope_spans:
                for span in ss.spans:
                    spans.append(span)

    print(f"Total spans: {len(spans)}")
    # Build a map of span_id hex -> name
    id_to_name = {}
    for s in spans:
        sid = s.span_id.hex()
        name = s.name
        # langwatch span type attribute
        span_type = ""
        for kv in s.attributes:
            if kv.key == "langwatch.span.type":
                span_type = kv.value.string_value
        id_to_name[sid] = (name, span_type, s.parent_span_id.hex())

    for s in spans:
        sid = s.span_id.hex()
        pid = s.parent_span_id.hex()
        name, stype, _ = id_to_name.get(sid, ("?", "", ""))
        parent_name = id_to_name.get(pid, (None, None, None))[0]
        print(
            f"span={name!r} type={stype!r} id={sid} "
            f"parent={parent_name!r} parent_id={pid if pid else '(root)'}"
        )


if __name__ == "__main__":
    decode(sys.argv[1] if len(sys.argv) > 1 else "/tmp/mock_captures/traces.raw.bin")

